<template>
  <div class="app-container">
    <el-alert title="会员数据来源：/cps/members，仅展示 sysWechatUser 对应的小程序会员；手机号由服务端打码。此页面只读，不提供账户、邀请关系或风控写操作。" type="info" :closable="false" />
    <el-form :model="query" ref="queryForm" :inline="true" size="small" label-width="88px" style="margin-top:14px"><el-form-item label="会员 ID"><el-input v-model="query.userId" clearable @keyup.enter.native="search"/></el-form-item><el-form-item label="昵称"><el-input v-model="query.nickname" clearable @keyup.enter.native="search"/></el-form-item><el-form-item label="手机号"><el-input v-model="query.phone" clearable @keyup.enter.native="search"/></el-form-item><el-form-item label="风险等级"><el-select v-model="query.riskLevel" clearable><el-option v-for="x in riskLevels" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" size="mini" @click="search">搜索</el-button><el-button icon="el-icon-refresh" size="mini" @click="reset">重置</el-button></el-form-item></el-form>
    <el-table v-loading="loading" :data="rows"><el-table-column label="会员" min-width="190"><template slot-scope="s"><div class="profile"><el-avatar :size="32" :src="s.row.avatar">{{(s.row.nickname||'会').slice(0,1)}}</el-avatar><div><div>{{s.row.nickname||'未设置昵称'}}</div><small>ID {{s.row.userId}}</small></div></div></template></el-table-column><el-table-column label="手机号" prop="phoneMasked" width="140"/><el-table-column label="风险等级" prop="riskLevel" width="110"><template slot-scope="s"><el-tag :type="riskType(s.row.riskLevel)">{{s.row.riskLevel||'未评估'}}</el-tag></template></el-table-column><el-table-column label="邀请码" prop="invitationCode" width="120"/><el-table-column label="邀请人 ID" prop="inviterUserId" width="120"/><el-table-column label="可用余额" prop="balance" width="125"><template slot-scope="s">¥{{money(s.row.balance)}}</template></el-table-column><el-table-column label="冻结金额" prop="frozenAmount" width="125"><template slot-scope="s">¥{{money(s.row.frozenAmount)}}</template></el-table-column><el-table-column label="提现中" prop="withdrawingAmount" width="120"><template slot-scope="s">¥{{money(s.row.withdrawingAmount)}}</template></el-table-column><el-table-column label="累计已提现" prop="withdrawn" width="130"><template slot-scope="s">¥{{money(s.row.withdrawn)}}</template></el-table-column><el-table-column label="累计收入" prop="totalEarned" width="125"><template slot-scope="s">¥{{money(s.row.totalEarned)}}</template></el-table-column><el-table-column label="账户状态" prop="accountStatus" width="110"/><el-table-column label="注册时间" prop="createTime" min-width="170"/><el-table-column label="操作" width="90" fixed="right"><template slot-scope="s"><el-button type="text" size="mini" @click="detail(s.row)" v-hasPermi="['system:commission:user:query']">详情</el-button></template></el-table-column></el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
    <el-drawer title="小程序会员资料" :visible.sync="open" size="600px" append-to-body v-loading="detailLoading"><el-descriptions v-if="detailData.userId" :column="1" border><el-descriptions-item label="会员 ID">{{detailData.userId}}</el-descriptions-item><el-descriptions-item label="昵称">{{detailData.nickname||'未设置'}}</el-descriptions-item><el-descriptions-item label="手机号">{{detailData.phoneMasked||'未绑定'}}</el-descriptions-item><el-descriptions-item label="风险等级">{{detailData.riskLevel||'未评估'}}</el-descriptions-item><el-descriptions-item label="邀请码">{{detailData.invitationCode||'-'}}</el-descriptions-item><el-descriptions-item label="邀请人 ID">{{detailData.inviterUserId||'-'}}</el-descriptions-item><el-descriptions-item label="可用余额">¥{{money(detailData.balance)}}</el-descriptions-item><el-descriptions-item label="冻结金额">¥{{money(detailData.frozenAmount)}}</el-descriptions-item><el-descriptions-item label="提现中">¥{{money(detailData.withdrawingAmount)}}</el-descriptions-item><el-descriptions-item label="累计已提现">¥{{money(detailData.withdrawn)}}</el-descriptions-item><el-descriptions-item label="累计收入">¥{{money(detailData.totalEarned)}}</el-descriptions-item><el-descriptions-item label="账户状态">{{detailData.accountStatus}}</el-descriptions-item><el-descriptions-item label="注册时间">{{detailData.createTime}}</el-descriptions-item></el-descriptions></el-drawer>
  </div>
</template>
<script>
import { memberRows,memberDetail,cpsDict } from '@/api/cps/settings'
export default {name:'CpsMembers',data(){return{loading:false,detailLoading:false,rows:[],total:0,open:false,detailData:{},query:{pageNum:1,pageSize:10,userId:'',nickname:'',phone:'',riskLevel:''},riskLevels:[]}},created(){cpsDict().then(r=>{this.riskLevels=(r.data&&r.data.riskLevels)||[]});this.load()},methods:{load(){this.loading=true;memberRows(this.query).then(r=>{this.rows=(r.data&&r.data.rows)||[];this.total=(r.data&&r.data.total)||0}).finally(()=>{this.loading=false})},search(){this.query.pageNum=1;this.load()},reset(){this.$refs.queryForm.resetFields();this.query.pageNum=1;this.load()},detail(row){this.open=true;this.detailLoading=true;memberDetail(row.userId).then(r=>{this.detailData=r.data||{}}).finally(()=>{this.detailLoading=false})},money(v){return v==null?'0.00':Number(v).toFixed(2)},riskType(v){return ({高风险:'danger',中风险:'warning',低风险:'success',正常:'success'})[v]||'info'}}}
</script>
<style scoped>.profile{display:flex;align-items:center;gap:10px}.profile small{color:#909399}</style>
